import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 size 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const ROLE = '예산·회계 담당자';
const EVIDENCE_TYPES = ['통장', '카드', '현금영수증', '전자세금계산서'];
const USE_YN = ['사용', '미사용'];

interface SettingInput {
  evidenceType: string;
  evidenceItem: string;
  collectionEnabled: boolean;
  autoJournalEnabled: boolean;
  accountItemId: string;
  useYn: string;
}

function invalid(message: string): ApiError {
  return new ApiError(422, 'VOUCHER_EVIDENCE_SETTING_INVALID', message);
}

function readSetting(data: Record<string, unknown>): SettingInput {
  const evidenceType = data['evidenceType'];
  if (typeof evidenceType !== 'string' || !EVIDENCE_TYPES.includes(evidenceType)) {
    throw invalid('증빙유형은 통장, 카드, 현금영수증, 전자세금계산서 중 하나여야 합니다.');
  }
  const evidenceItem = data['evidenceItem'];
  if (typeof evidenceItem !== 'string' || evidenceItem.trim().length === 0 || evidenceItem.length > 200) {
    throw invalid('증빙항목은 1자 이상 200자 이하로 입력해 주세요.');
  }
  const collectionEnabled = data['collectionEnabled'];
  if (typeof collectionEnabled !== 'boolean') {
    throw invalid('자료수집 여부를 지정해 주세요.');
  }
  const autoJournalEnabled = data['autoJournalEnabled'];
  if (typeof autoJournalEnabled !== 'boolean') {
    throw invalid('자동분개 처리 여부를 지정해 주세요.');
  }
  const raw = data['accountItemId'];
  const validNumber = typeof raw === 'number' && Number.isInteger(raw) && raw > 0;
  const validString = typeof raw === 'string' && /^\d+$/.test(raw);
  if (!validNumber && !validString) {
    throw invalid('계정과목을 지정해 주세요.');
  }
  const useYn = data['useYn'];
  if (typeof useYn !== 'string' || !USE_YN.includes(useYn)) {
    throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  return {
    evidenceType,
    evidenceItem: evidenceItem.trim(),
    collectionEnabled,
    autoJournalEnabled,
    accountItemId: String(raw),
    useYn,
  };
}

type Db = {
  query: (sql: string, params?: Record<string, unknown>) => Promise<any[]>;
  execute: (sql: string, params?: Record<string, unknown>) => Promise<number>;
};

async function checkAccountItem(db: Db, accountItemId: string): Promise<void> {
  const rows = await db.query(
    'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:accountItemId AS bigint)',
    { accountItemId },
  );
  if (rows.length === 0) {
    throw new ApiError(422, 'ACCOUNT_ITEM_UNUSABLE', '자동분개 계정과목이 존재하지 않거나 사용할 수 없습니다.');
  }
}

async function checkDuplicate(db: Db, v: SettingInput, excludeId: string | null): Promise<void> {
  const rows = await db.query(
    'SELECT voucher_evidence_setting_id FROM voucher_evidence_setting '
      + 'WHERE evidence_type = :evidenceType AND evidence_item = :evidenceItem '
      + 'AND account_item_id = CAST(:accountItemId AS bigint) '
      + 'AND (CAST(:excludeId AS bigint) IS NULL OR voucher_evidence_setting_id <> CAST(:excludeId AS bigint))',
    { evidenceType: v.evidenceType, evidenceItem: v.evidenceItem, accountItemId: v.accountItemId, excludeId },
  );
  if (rows.length > 0) {
    throw invalid('같은 증빙유형·증빙항목·계정과목의 설정이 이미 있습니다.');
  }
}

@Controller('api/v1')
export class FnSfr00701Controller {
  @Get('/voucher-evidence-settings')
  async listVoucherEvidenceSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const evidenceTypeRaw = query['evidenceType'];
    const useYnRaw = query['useYn'];
    const evidenceType = typeof evidenceTypeRaw === 'string' && evidenceTypeRaw !== '' ? evidenceTypeRaw : null;
    const useYn = typeof useYnRaw === 'string' && useYnRaw !== '' ? useYnRaw : null;
    if (evidenceType !== null && !EVIDENCE_TYPES.includes(evidenceType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '증빙유형 조건이 올바르지 않습니다.');
    }
    if (useYn !== null && !USE_YN.includes(useYn)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '사용 여부 조건이 올바르지 않습니다.');
    }
    const pageRaw = query['page'];
    const sizeRaw = query['size'];
    const page = pageRaw === undefined || pageRaw === '' ? 0 : Number(pageRaw);
    let size = sizeRaw === undefined || sizeRaw === '' ? DEFAULT_SIZE : Number(sizeRaw);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page와 size 값이 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const where = 'WHERE (CAST(:evidenceType AS text) IS NULL OR evidence_type = CAST(:evidenceType AS text)) '
        + 'AND (CAST(:useYn AS text) IS NULL OR use_yn = CAST(:useYn AS text))';
      const items = await db.query(
        'SELECT voucher_evidence_setting_id AS "voucherEvidenceSettingId", '
          + 'evidence_type AS "evidenceType", '
          + 'evidence_item AS "evidenceItem", '
          + 'collection_enabled AS "collectionEnabled", '
          + 'auto_journal_enabled AS "autoJournalEnabled", '
          + 'account_item_id AS "accountItemId", '
          + 'use_yn AS "useYn" '
          + 'FROM voucher_evidence_setting ' + where + ' '
          + 'ORDER BY voucher_evidence_setting_id DESC LIMIT :size OFFSET :offset',
        { evidenceType, useYn, size, offset: page * size },
      );
      const totals = await db.query(
        'SELECT COUNT(*) AS "total" FROM voucher_evidence_setting ' + where,
        { evidenceType, useYn },
      );
      return { items, page, size, total: Number(totals[0].total) };
    });
  }

  @Post('/voucher-evidence-settings')
  @HttpCode(200)
  async createVoucherEvidenceSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const v = readSetting(data);
    return transaction(async (db) => {
      await checkAccountItem(db, v.accountItemId);
      await checkDuplicate(db, v, null);
      const rows = await db.query(
        'INSERT INTO voucher_evidence_setting '
          + '(account_item_id, evidence_type, evidence_item, collection_enabled, auto_journal_enabled, use_yn, created_at, updated_at) '
          + 'VALUES (CAST(:accountItemId AS bigint), :evidenceType, :evidenceItem, :collectionEnabled, :autoJournalEnabled, :useYn, now(), now()) '
          + 'RETURNING voucher_evidence_setting_id AS "voucherEvidenceSettingId"',
        { ...v },
      );
      return { voucherEvidenceSettingId: Number(rows[0].voucherEvidenceSettingId) };
    });
  }

  @Put('/voucher-evidence-settings/:voucherEvidenceSettingId')
  async updateVoucherEvidenceSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['voucherEvidenceSettingId'];
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const v = readSetting(data);
    return transaction(async (db) => {
      if (!/^\d+$/.test(id)) {
        throw new ApiError(404, 'VOUCHER_EVIDENCE_SETTING_NOT_FOUND', '증빙·자동분개 설정을 찾을 수 없습니다.');
      }
      const found = await db.query(
        'SELECT voucher_evidence_setting_id FROM voucher_evidence_setting WHERE voucher_evidence_setting_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'VOUCHER_EVIDENCE_SETTING_NOT_FOUND', '증빙·자동분개 설정을 찾을 수 없습니다.');
      }
      await checkAccountItem(db, v.accountItemId);
      await checkDuplicate(db, v, id);
      await db.execute(
        'UPDATE voucher_evidence_setting SET '
          + 'account_item_id = CAST(:accountItemId AS bigint), '
          + 'evidence_type = :evidenceType, '
          + 'evidence_item = :evidenceItem, '
          + 'collection_enabled = :collectionEnabled, '
          + 'auto_journal_enabled = :autoJournalEnabled, '
          + 'use_yn = :useYn, '
          + 'updated_at = now() '
          + 'WHERE voucher_evidence_setting_id = CAST(:id AS bigint)',
        { ...v, id },
      );
      return { voucherEvidenceSettingId: Number(id) };
    });
  }
}

