import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  Select,
  TextInput,
  LookupSelect,
  RefName,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const EVIDENCE_TYPES: [string, string][] = [
  ['통장', '통장'],
  ['카드', '카드'],
  ['현금영수증', '현금영수증'],
  ['전자세금계산서', '전자세금계산서'],
];
const USE_YN: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];
const YES_NO: [string, string][] = [
  ['true', '예'],
  ['false', '아니오'],
];
const SIZE = 20;

function SettingForm({ role, notify, row, onDone }: {
  role: string;
  notify: (text: string) => void;
  row: Row | null;
  onDone: () => void;
}) {
  const [evidenceType, setEvidenceType] = useState<string>(row ? String(row.evidenceType) : '');
  const [evidenceItem, setEvidenceItem] = useState<string>(row ? String(row.evidenceItem) : '');
  const [collectionEnabled, setCollectionEnabled] = useState<string>(row ? String(row.collectionEnabled) : 'true');
  const [autoJournalEnabled, setAutoJournalEnabled] = useState<string>(row ? String(row.autoJournalEnabled) : 'true');
  const [accountItemId, setAccountItemId] = useState<number | string>(row ? (row.accountItemId as number) : '');
  const [useYn, setUseYn] = useState<string>(row ? String(row.useYn) : '사용');

  async function submit() {
    if (!evidenceType) {
      throw new Error('증빙유형을 선택해 주세요.');
    }
    if (!evidenceItem.trim()) {
      throw new Error('증빙항목을 입력해 주세요.');
    }
    if (accountItemId === '') {
      throw new Error('계정과목을 선택해 주세요.');
    }
    const body: Row = {
      evidenceType,
      evidenceItem: evidenceItem.trim(),
      collectionEnabled: collectionEnabled === 'true',
      autoJournalEnabled: autoJournalEnabled === 'true',
      accountItemId,
      useYn,
    };
    if (row) {
      await call('PUT', '/voucher-evidence-settings/' + String(row.voucherEvidenceSettingId), role, body);
      notify('증빙·자동분개 설정을 수정했습니다.');
    } else {
      await call('POST', '/voucher-evidence-settings', role, body);
      notify('증빙·자동분개 설정을 등록했습니다.');
    }
    onDone();
  }

  return (
    <Form onSubmit={submit} submit={row ? '수정' : '등록'}>
      <Field label='증빙유형' required>
        <Select value={evidenceType} onChange={setEvidenceType} options={EVIDENCE_TYPES} />
      </Field>
      <Field label='증빙항목' required>
        <TextInput value={evidenceItem} onChange={setEvidenceItem} />
      </Field>
      <Field label='자료수집 여부' required>
        <Select value={collectionEnabled} onChange={setCollectionEnabled} options={YES_NO} />
      </Field>
      <Field label='자동분개 처리 여부' required>
        <Select value={autoJournalEnabled} onChange={setAutoJournalEnabled} options={YES_NO} />
      </Field>
      <Field label='계정과목' required>
        <LookupSelect table='account_item' role={role} value={accountItemId} onChange={setAccountItemId} />
      </Field>
      <Field label='사용 여부' required>
        <Select value={useYn} onChange={setUseYn} options={USE_YN} />
      </Field>
    </Form>
  );
}

export default function FnSfr00701Page({ role, notify }: PageProps) {
  const [typeInput, setTypeInput] = useState('');
  const [useInput, setUseInput] = useState('');
  const [applied, setApplied] = useState({ evidenceType: '', useYn: '' });
  const [page, setPage] = useState(0);
  const [drawer, setDrawer] = useState<{ row: Row | null } | null>(null);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/voucher-evidence-settings', role, undefined, {
      evidenceType: applied.evidenceType,
      useYn: applied.useYn,
      page,
      size: SIZE,
    }),
    [role, applied, page],
  );

  function search() {
    setPage(0);
    setApplied({ evidenceType: typeInput, useYn: useInput });
  }

  function reset() {
    setTypeInput('');
    setUseInput('');
    setPage(0);
    setApplied({ evidenceType: '', useYn: '' });
  }

  function done() {
    setDrawer(null);
    reload();
  }

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>전체 설정</h2>
        <Num value={data ? data.total : 0} />
      </section>
      <section className='box span-8'>
        <h2>증빙 설정 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='증빙유형'>
            <Select value={typeInput} onChange={setTypeInput} options={EVIDENCE_TYPES} placeholder='전체' />
          </Field>
          <Field label='사용 여부'>
            <Select value={useInput} onChange={setUseInput} options={USE_YN} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type='button' onClick={() => setDrawer({ row: null })}>설정 등록</button>
        </Band>
        {error ? <p>{error}</p> : null}
        <DataTable
          rows={data ? data.items : []}
          onRowClick={(row) => setDrawer({ row })}
          empty='등록된 설정이 없습니다.'
          columns={[
            { key: 'evidenceType', label: '증빙유형' },
            { key: 'evidenceItem', label: '증빙항목' },
            { key: 'collectionEnabled', label: '자료수집 여부', render: (r) => (r.collectionEnabled ? '예' : '아니오') },
            { key: 'autoJournalEnabled', label: '자동분개 처리 여부', render: (r) => (r.autoJournalEnabled ? '예' : '아니오') },
            { key: 'accountItemId', label: '계정과목', render: (r) => <RefName table='account_item' role={role} value={r.accountItemId} /> },
            { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r.useYn} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {drawer ? (
        <Drawer title={drawer.row ? '증빙·자동분개 설정 수정' : '증빙·자동분개 설정 등록'} onClose={() => setDrawer(null)}>
          <SettingForm role={role} notify={notify} row={drawer.row} onDone={done} />
        </Drawer>
      ) : null}
    </div>
  );
}
